(()=>{
const pending=new Set(),busy=j=>['submitting','queued','running','waiting'].includes(j?.status);
function batchBusy(c){return pending.has(c)||(c.portraitCandidates?.jobs||[]).some(busy);}
function applyCandidate(c,job){const batch=c.portraitCandidates;if(batch?.request_id===job.id){batch.status=job.status;if(job.candidates){batch.jobs=job.candidates;for(const item of batch.jobs){c.portraitVersions??=[];if(!c.portraitVersions.some(v=>v.id===item.id))c.portraitVersions.push({...item});}}else batch.jobs=batch.jobs.map(item=>({...item,status:job.status,error:job.error}));c.portraitJob={...job};save();return true;}const index=batch?.jobs.findIndex(j=>j.id===job.id);if(index==null||index<0)return false;batch.jobs[index]={...batch.jobs[index],...job};if(job.status==='completed'){c.portraitVersions??=[];if(!c.portraitVersions.some(v=>v.id===job.id))c.portraitVersions.push({...job});}const active=batch.jobs.find(busy);c.portraitJob=active?{...active,status:'running'}:{...batch.jobs[0],status:batch.jobs.some(j=>j.status==='completed')?'completed':'failed'};save();return true;}
const priorApply=applyIdentityPortrait;applyIdentityPortrait=function(c,job){if(!applyCandidate(c,job))priorApply(c,job);};
generateIdentityPortrait=async function(c){if(batchBusy(c)||roleIsBusy(c)||c.oneClick?.status==='running'){toast('请先等待当前角色任务完成');return;}const prompt=portraitPromptFor(c);if(!prompt.trim()){toast('请先填写大头像提示词');return;}pending.add(c);const batch={id:crypto.randomUUID(),request_id:crypto.randomUUID(),jobs:Array.from({length:4},()=>({id:crypto.randomUUID(),status:'submitting'})),created_at:new Date().toISOString()};c.portraitCandidates=batch;c.portraitJob={...batch.jobs[0]};save();render();try{try{const job=await frontFetch('/api/front-image',{request_id:batch.request_id,batch_size:4,port:Number(localStorage.getItem('frame-comfy-port')||8188),mode:'portrait',project_id:data.project_id||data.title,character_id:c.id||c.character_id||c.name,character_name:c.name,prompt,negative_prompt:c.negativePrompt||'',style:data.style||'',background:c.nonWhiteBackground?'gray':'white',...CharacterSheet.spec.view_sizes.portrait});applyCandidate(c,job);}catch(e){applyCandidate(c,{id:batch.request_id,status:'failed',error:e.message});}toast('已提交一个批次，共4张大头像，完成后请选择一张采用');}finally{pending.delete(c);if(tab===0)render();}};
let polling=false;setInterval(async()=>{if(polling)return;polling=true;try{let changed=false;for(const c of data.characters){if(pending.has(c))continue;if(c.portraitCandidates?.request_id){if(busy(c.portraitJob)){try{applyCandidate(c,await frontFetch('/api/front-image/'+c.portraitCandidates.request_id));changed=true;}catch{}}continue;}for(const task of c.portraitCandidates?.jobs||[]){if(!busy(task))continue;try{applyCandidate(c,await frontFetch('/api/front-image/'+task.id));changed=true;}catch{}}}if(changed&&tab===0)render();}finally{polling=false;}},3000);
const loadingStyle=document.createElement('style');loadingStyle.textContent='.portrait-generating{min-height:260px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;color:var(--green);width:100%;box-sizing:border-box}.portrait-generating-spin{width:30px;height:30px;border:3px solid #30463f;border-top-color:#b5e3d2;border-radius:50%;animation:portraitSpin 1s linear infinite}@keyframes portraitSpin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.portrait-generating-spin{animation:none}}';document.head.append(loadingStyle);
function portraitLoading(c,batch){const running=batchBusy(c),waiting=!running&&batch&&!batch.selected_id&&batch.jobs.some(j=>j.status==='completed');if(!running&&!waiting)return;const message=running?'正在生成4张大头像…':'4张大头像已生成，请选择采用';const placeholder=()=>{const box=document.createElement('div');box.className='portrait-generating';box.setAttribute('role','status');if(running){const spin=document.createElement('span');spin.className='portrait-generating-spin';spin.setAttribute('aria-hidden','true');box.append(spin);}const text=document.createElement('span');text.textContent=message;box.append(text);return box;};const art=document.querySelector('#panel .artboard');if(art)art.replaceChildren(placeholder());const angle=document.querySelector('#panel .angle-grid .angle');if(angle){angle.querySelectorAll('img,.role-image-tools,.image-resolution-label,.portrait-generating').forEach(e=>e.remove());angle.prepend(placeholder());}}
const priorCharacters=characters;characters=function(){priorCharacters();const c=data.characters[ci],batch=c?.portraitCandidates;if(!c)return;portraitLoading(c,batch);const generate=document.querySelector('#generate');if(generate){generate.textContent=batchBusy(c)?'正在生成4张大头像…':'生成4张大头像供选择';generate.disabled=batchBusy(c)||c.oneClick?.status==='running';}if(!batch)return;if(batch.selected_id&&!batchBusy(c)){const actions=document.createElement('div');actions.style.cssText='display:flex;gap:12px;flex-wrap:wrap;margin:16px 0';const next=document.createElement('button');next.className='primary';next.textContent=c.oneClick?.status==='running'?'正在生成全身、侧面和背面…':'继续生成全身、侧面和背面';next.disabled=c.oneClick?.status==='running';next.onclick=()=>{c.view='multi';save();startCharacterAuto(c,false,{use_selected_portrait:true});};const choose=document.createElement('button');choose.textContent='重新选择大头像';choose.disabled=c.oneClick?.status==='running';choose.onclick=()=>{delete batch.selected_id;c.view='portrait';save();render();};actions.append(next,choose);const preview=document.querySelector('#panel .artboard');if(preview)preview.after(actions);else document.querySelector('#panel .angle-grid')?.before(actions);return;}const section=document.createElement('section');section.className='card';section.id='portraitCandidates';section.innerHTML='<h3>大头像候选 · 选择一张采用</h3><p class="subtle">共4张；选中后作为全身、侧面和背面的身份参考。旧图保留在历史版本中。</p><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px">'+batch.jobs.map((j,i)=>'<div><b>候选 '+(i+1)+'</b>'+(j.image_url?'<a href="'+esc(j.image_url)+'" target="_blank" rel="noopener"><img src="'+esc(j.image_url)+'" alt="'+esc(c.name)+' 大头像候选'+(i+1)+'" style="width:100%;height:clamp(320px,42vw,580px);object-fit:contain"></a>':'<div class="portrait-generating"><span class="portrait-generating-spin" aria-hidden="true"></span><p>'+esc(j.error||({submitting:'准备提交',queued:'排队中',running:'生成中',waiting:'等待结果',failed:'生成失败'})[j.status]||j.status)+'</p></div>')+'<button data-portrait-candidate="'+i+'" '+(j.status!=='completed'||batchBusy(c)?'disabled':'')+'>'+((batch.selected_id===j.id)?'✓ 已采用':'采用这张大头像')+'</button></div>').join('')+'</div>';const preview=document.querySelector('#panel .artboard');section.style.cssText='width:100%;min-width:0;box-sizing:border-box;text-align:left;margin:0';if(preview){preview.style.cssText+=';height:auto;min-height:360px;display:block;padding:12px;box-sizing:border-box;overflow:visible';preview.replaceChildren(section);}else{const grid=document.querySelector('#panel .angle-grid');if(grid)grid.before(section);else document.querySelector('#panel').append(section);}section.querySelectorAll('[data-portrait-candidate]').forEach(b=>b.onclick=()=>{const job=batch.jobs[Number(b.dataset.portraitCandidate)];c.identityPortrait={...job};c.portraitConfirmed=true;c.portraitConfirmedId=job.id;c.confirmed=false;c.stale=!!c.versions?.length;c.reference_images??={};c.reference_images.portrait=job.image_url;const entry=activeMulti(c);if(entry){entry.jobs??={};entry.jobs.portrait={...job,identity_master:true};}batch.selected_id=job.id;save();render();toast('已采用这张大头像');});};
const priorAuto=startCharacterAuto;startCharacterAuto=async function(c,resume=false,options={}){if(batchBusy(c)){toast('请等待4张大头像生成完成并选择');return;}if(options.batch_id){if(c.portraitCandidates){c.portraitCandidateHistory??=[];c.portraitCandidateHistory.push(c.portraitCandidates);delete c.portraitCandidates;save();}return priorAuto(c,resume,{...options,fill_missing:true});}if(!resume&&(!c.portraitConfirmed||c.portraitConfirmedId!==currentIdentityPortrait(c)?.id)){if(c.portraitCandidates?.jobs.some(j=>j.status==='completed')){c.view='portrait';save();render();toast('请先从4张候选中选择大头像，再继续生成其他角度');return;}await generateIdentityPortrait(c);return;}return priorAuto(c,resume,{...options,fill_missing:true});};
render();
})();
